def add(n,stem,opts,ans,analysis,why,pages,keys=(),qtype=None):
 R.append({'number':n,'section':'政治理论' if n<=10 else '常识应用','question_type':qtype or ('true_false' if n<=4 else 'multiple_choice' if n in [9,10] else 'single_choice'),'source_bank':'editor_original','source_id':f'M02-ORIG-{n:03d}','stem':stem,'options':opts,'answer':ans,'analysis':analysis,'selection_reason':why,'source_question':None,'source_answer':None,'edits':[],
 'verification':{'status':'editor_checked_pending_claude','method':'按用户讲义主题原创；逐项检查概念与证据，时政、法律和专门事实另列实际核对的一手或政府发布依据。','checked_on':'2026-11-15','external_review':'pending_claude'},
 'provenance':{'kind':'original','book':'学习资料/政治理论常识/颜培天广东政治理论常识.pages.jsonl','book_pages':pages,'references':[refs[k] for k in keys]},'figures':[],'materials':[]})
add(1,'根据党的二十届五中全会公报，增强党性属于全面从严治党的根本性任务，从严治吏是全面从严治党的关键。',{},'正确','正确。2026年10月29日通过的公报分别强调党性锤炼的根本性和从严管理干部的关键地位，两者回答的侧重点不同，并不矛盾。此题以已查到的正式公报为依据，不单凭讲义对新近会议的转录。','覆盖新近全会，同时辨清根本性任务与关键环节的不同层次。',[6,10],['fifth'])
add(2,'企业用货币支付已经到期的职工工资，体现的是货币的流通手段职能。',{},'错误','错误。到期工资的支付是在清偿已经形成的工资给付关系，属于货币支付手段；流通手段通常指货币在商品直接买卖中充当交换媒介。不能因为钱在转手就将各种货币给付都归为流通手段。','用具体给付情境区分货币两种易混淆职能。',[45])
add(3,'把马克思主义基本原理同中华优秀传统文化相结合，意味着二者在结合中相互成就，而不是把传统文化的全部内容原封不动地搬入现代社会。',{},'正确','正确。“第二个结合”不是简单拼接，强调以新的理论视野激活优秀传统文化并推动现代转化。题干同时保留“优秀”这一选择与创造性转化要求，不等于照搬历史上的所有观念和制度。','文化理论判断兼顾结合与转化的边界，避免把传承理解为复原。',[20,31,32],['culture'])
add(4,'区分不变资本和可变资本，主要依据是资本的价值能否在一次生产过程中全部转移到新产品中。',{},'错误','错误。二者按资本在剩余价值生产中所起作用区分，而不是按一次还是分次转移价值区分。原材料即使在一次生产中消耗并转移价值，仍属不变资本；购买劳动力的资本对应劳动者创造新价值的过程，属于可变资本。这里考查马克思主义政治经济学的概念，不把名称中的“不变”误读为物品不耗损。','将剩余价值作用与价值转移方式分开，避免望文生义。',[46])
add(5,'依据党的二十届五中全会公报，下列关于持之以恒推进全面从严治党的表述，正确的是（　）。',{'A':'以党的组织建设为统领，全面推进党的各方面建设','B':'党的各级组织都承担主体职责，需要体系化加强不同层级和领域的党组织建设','C':'由纪检监察机关代替党委（党组）承担全面监督责任','D':'以党的纪律处分条例作为全党的根本行为规范'},'B','B符合公报对主体和组织体系的要求。A把政治建设的统领地位换成组织建设；C把不同主体的监督职责合并替代；D把党章的根本地位换成了一部具体党内法规。三项均是主体、层级或制度地位错置，而不是因为出现某个政治关键词就可以判对。','以原文核心概念的实质替换构造干扰项，不使用夸张绝对词。',[5,12,18,19],['fifth'])
add(6,'2026年广东省高质量发展大会以制造业与服务业协同发展为主题。下列举措中，最直接体现“两业协同融合”的是（　）。',{'A':'制造企业增加相同生产线，扩大现有标准化产品的产量','B':'商贸企业建设大型购物中心，增加本地休闲消费供给','C':'设计服务企业与制造企业联合开发定制产品，并把检测、运维服务嵌入产品全生命周期','D':'生产企业将旧厂房出售给房地产企业，主要依靠资产处置获取当期收益'},'C','C使设计、检测、运维等服务进入制造的研发生产和使用环节，形成产品与服务共同供给，直接体现协同融合。A主要是制造规模扩大，B主要是消费服务供给增加，D是资产处置，均没有呈现两类产业在生产价值链上的协作。选项中的企业行为为命题情境，不冒称真实项目。','用产业关系而非产业名称判断两业协同，覆盖当年广东会议主题。',[67,68,69],['conference','industries'])
add(7,'某县评价产业转型时，既看到少数企业调整期的经营困难，也看到技术升级、产品质量改善等积极因素已在整体发展中占据主导地位，因此判断总体态势向好。这一判断最直接体现了（　）。',{'A':'在复杂事物中，解决主要矛盾即可代替对其他矛盾的分析','B':'把握矛盾的主要方面，并在看到主流时不忽略支流','C':'事物的数量增加本身就标志着其根本性质已经改变','D':'事物内部各方面的地位相同，应当赋予相同判断权重'},'B','题干在评价事物整体态势，依据是积极因素占据主导，同时承认局部困难，体现主要方面与次要方面的辩证关系，选B。它不是在许多待解决任务中寻找最主要的那一个矛盾。A还错误地把抓主要矛盾说成可以不看其他矛盾；C混淆量变与质变；D否认主次地位差异。','把判断性质的主要方面与处理任务的主要矛盾区分开。',[41])
add(8,'关于初次分配、再分配和第三次分配，下列归类正确的是（　）。',{'A':'企业依据劳动贡献支付职工绩效奖金——初次分配','B':'政府运用税收收入发放基本生活救助——第三次分配','C':'个人出于自愿向公益慈善项目捐赠——再分配','D':'企业向投资者分配生产经营收益——政府再分配'},'A','工资、奖金和生产要素参与经营成果分配属于初次分配，A正确。B是政府调节形成的再分配，C是自愿公益慈善的第三次分配，D把经营收益分配错归政府再分配。区分依据是机制和主体，不是款项发放的先后时间。','用实际收入流动辨别分配机制，不把序数名称当时间顺序。',[26,27],['distribution'])
add(9,'根据党的二十届四中全会公报及中国式现代化的战略安排，下列表述正确的有（　）。',{'A':'“十五五”时期是基本实现社会主义现代化夯实基础、全面发力的关键时期','B':'到2035年基本实现社会主义现代化，是分两步走战略安排的第一步','C':'到2035年全面建成富强民主文明和谐美丽的社会主义现代化强国','D':'“十五五”时期发展要坚持以经济建设为中心、以推动高质量发展为主题'},'ABD','A、D对应四中全会公报的阶段定位与发展要求；B对应2035年的阶段目标。C把本世纪中叶的强国目标前移到2035年，混淆两步走的时间层次。题目明确依据四中全会和战略安排，不把它误标为五中全会通过的规划建议。','将会议内容、规划期与两阶段目标连接核验。',[23,62,63],['fourth','security'])
add(10,'关于总体国家安全观，下列对应关系正确的有（　）。',{'A':'人民安全——宗旨','B':'科技安全——根本','C':'经济安全——基础','D':'促进国际安全——依托'},'ACD','A、C、D正确。根本是政治安全，不是科技安全；科技安全与军事、文化、社会等安全共同构成保障的重要方面。各领域相互关联，不代表可以交换其特定政治定位。','在相近的层次词中核对安全观的结构，而不是罗列安全领域。',[34],['security'])
add(11,'甲去世时，其妻乙正在怀孕，遗产分割为胎儿保留了相应份额。根据《民法典》，下列说法正确的是（　）。',{'A':'胎儿出生前不具有任何受保护的利益，因此不应保留继承份额','B':'为胎儿保留份额，说明胎儿已具有完全民事行为能力','C':'若胎儿活体出生后死亡，不能因其后来死亡就认定其民事权利能力自始不存在','D':'若胎儿娩出时为死体，应先将预留份额认定为该胎儿自己的遗产'},'C','民法典第16条对继承、受赠等胎儿利益作特别保护，但胎儿娩出时为死体的，民事权利能力自始不存在。C的活体出生后死亡不同于娩出死体，不能适用“自始不存在”。A否定特别保护，B混淆权利能力与行为能力。D中死体胎儿并未取得该权利，预留份额不能先算作其遗产再继承；第1155条另规定此时按法定继承办理。','通过活体出生后死亡与娩出死体的对照，检验法律条件边界。',[93],['civil'])
add(12,'关于深中通道的地理位置与工程布局，下列说法正确的是（　）。',{'A':'东端位于深圳，西端直接连接澳门半岛','B':'位于港珠澳大桥以南，是珠江口最南侧的跨海通道','C':'采用东隧西桥布局，向西跨越珠江口，在中山登陆','D':'以横跨狮子洋、连接广州两岸为主要线路特征'},'C','深中通道从深圳一侧出发向西跨珠江口，在中山登陆，采用东隧西桥布局，C正确。西端不是澳门；它位于港珠澳大桥以北；D把深中通道与珠江口其他跨江工程的区位混淆。题目只采用稳定的区位和工程构成，不使用可能变化的实时车流或通行时间。','广东重大工程的空间定位，区分相邻跨江通道。',[76],['bridge'])
add(13,'在关于党的重要会议与指导思想的学习笔记中，下列记录准确的是（　）。',{'A':'遵义会议首次将毛泽东思想写入党章','B':'党的六届七中全会通过了将毛泽东思想写入党章的党章修正案','C':'党的七届二中全会首次正式确立毛泽东思想为党的指导思想','D':'党的七大把毛泽东思想确立为党的指导思想并写入党章'},'D','1945年党的七大通过的党章总纲明确了毛泽东思想的指导地位，D准确。遵义会议、六届七中全会、七届二中全会各有重要历史作用，但不是“指导思想入党章”这一事件的对应会议。需要区分领导地位、历史决议和党章确定指导思想这几种不同表述。','相近会议与标志性成果对应，不靠年代粗排。',[51,53,54],['party1945'])
add(14,'暗物质粒子探测、空间量子科学实验、空间X射线天文观测，依次主要对应的我国科学卫星是（　）。',{'A':'“悟空”号、“慧眼”号、“墨子”号','B':'“悟空”号、“墨子”号、“慧眼”号','C':'“墨子”号、“悟空”号、“慧眼”号','D':'“慧眼”号、“墨子”号、“悟空”号'},'B','“悟空”号是暗物质粒子探测卫星；“墨子”号开展空间量子科学实验；“慧眼”号为硬X射线调制望远镜卫星，服务于高能天体研究。三者对应B。不能因为都用于尖端空间研究就混淆粒子探测、量子通信实验和天文观测任务。','以三类不同技术任务作整组匹配，避免只背单个卫星名称。',[106,107],['satellite'])
add(15,'以唐代三省六部制的一般职掌为准，诏令的起草、审议封驳和具体行政执行，依次主要由哪三个机构承担（　）？',{'A':'中书省、门下省、尚书省','B':'中书省、尚书省、门下省','C':'门下省、中书省、尚书省','D':'尚书省、门下省、中书省'},'A','中书省负责起草诏令，门下省负责审议并可封驳，尚书省及其六部负责具体行政执行，选A。题目限定为一般职掌，不能把某一时期兼任、参与政事堂议事等具体变化，混同于制度分工的基本结构。','从权力运行环节理解机构分工，而不是孤立记机构名。',[97],['ministries'])
